INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(41511, 'Exodus 23:17', 'Exodus', 23, 17, 'هر کال باید په دغو درېو اخترونو کې ستاسو ټول نارینه زما یعنې ستاسو د څښتن تعالی د عبادت دپاره راشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_17.mp3', '', 1761754199, 1761754199),
(41512, 'Exodus 23:18', 'Exodus', 23, 18, 'کله چې تاسو ماته یو حیوان قرباني کوئ، د هغه سره خمیره ډوډۍ مه وړاندې کوئ. هغه حیوانات چې په دغو اخترونو کې ماته قرباني کیږي، د هغې وازګه باید تر سهاره پورې پاتې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_18.mp3', '', 1761754199, 1761754199),
(41513, 'Exodus 23:19', 'Exodus', 23, 19, 'هر کال د خپل څښتن خدای کور ته د خپل لومړني حاصل ډېرې ښې غلې دانې راوړئ. یو سېرلی د خپلې مور په شیدو کې مه پخوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_19.mp3', '', 1761754199, 1761754199),
(41514, 'Exodus 23:20', 'Exodus', 23, 20, 'ګورئ، زه ستاسو مخې ته یوه فرښته درلېږم چې په لاره کې ستاسو ساتنه وکړي او هغه ځای ته مو راولي چې ستاسو دپاره مې تیار کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_20.mp3', '', 1761754199, 1761754199),
(41515, 'Exodus 23:21', 'Exodus', 23, 21, 'هرڅه چې هغه فرښته وایي په غور سره ورڅخه اطاعت وکړئ. د هغې په وړاندې سرکښي مه کوئ، هغه به ستاسو سرکښي ونه بخښي، ځکه چې پوره اختیار مې ورته ورکړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_21.mp3', '', 1761754199, 1761754199),
(41516, 'Exodus 23:22', 'Exodus', 23, 22, 'که چېرې تاسو په غور سره د هغې خبرو ته غوږ ونیسئ او هرڅه چې زه درته وایم هغه وکړئ، نو زه به ستاسو د دښمنانو دښمن شم او زه به د هغه چا په خلاف شم چې ستاسو په خلاف وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_22.mp3', '', 1761754199, 1761754199),
(41517, 'Exodus 23:23', 'Exodus', 23, 23, 'زما فرښته به ستاسو په مخکې روانه وي او تاسو به د اموریانو، حیتیانو، فرزیانو، کنعانیانو، حویانو او یبوسیانو خاورې ته بوځي او زه به هغوی ټول له منځه یوسم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_23.mp3', '', 1761754199, 1761754199),
(41518, 'Exodus 23:24', 'Exodus', 23, 24, 'د هغوی خدایانو ته سجده یا عبادت مه کوئ او د هغوی د رواجونو څخه پیروي مه کوئ. د هغوی بتان له منځه یوسئ او هغه لویې تیږې چې د هغوی د عبادت دپاره ورڅخه کار اخیستل کیږي، ټوټې ټوټې کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_24.mp3', '', 1761754199, 1761754199),
(41519, 'Exodus 23:25', 'Exodus', 23, 25, 'که چېرې تاسو زما یعنې د خپل څښتن خدای عبادت وکړئ، نو زه به ستاسو په خوراک او اوبو کې برکت واچوم او ستاسو ټولې ناروغۍ به لېرې کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_25.mp3', '', 1761754199, 1761754199),
(41520, 'Exodus 23:26', 'Exodus', 23, 26, 'ستاسو په خاوره کې به هېڅ یوه ښځه خپل اولاد نقصان نه کړي او نه به شنډه شي. زه به تاسو ته اوږده عمرونه درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_26.mp3', '', 1761754199, 1761754199),
(41521, 'Exodus 23:27', 'Exodus', 23, 27, 'زه به په هغو قومونو باندې سخته وېره راولم او ستاسو دښمنان به دومره وارخطا کړم چې درڅخه وتښتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_27.mp3', '', 1761754199, 1761754199),
(41522, 'Exodus 23:28', 'Exodus', 23, 28, 'زه به ستاسو په دښمنانو کې سخته وېره پیدا کړم او حویان، کنعانیان او حیتیان به ستاسو له مخې څخه لېرې کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_28.mp3', '', 1761754199, 1761754199),
(41523, 'Exodus 23:29', 'Exodus', 23, 29, 'خو زه به هغوی په یو کال کې ونه باسم، ځکه چې ځمکه به ویجاړه پاتې شي او وحشي حیوانات به ډېر زیات شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_29.mp3', '', 1761754199, 1761754199),
(41524, 'Exodus 23:30', 'Exodus', 23, 30, 'بلکې هغوی به لږ لږ شړم، ترڅو تاسو دومره ډېر شئ چې هغه خاوره ونیسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_30.mp3', '', 1761754199, 1761754199),
(41525, 'Exodus 23:31', 'Exodus', 23, 31, 'زه به ستاسو د خاورې سرحدونه د سرې بحیرې څخه نیولې د مدیترانې تر بحیرې پورې او د دښتې څخه نیولې د فرات تر سینده پورې وغزوم. زه به تاسو سره مرسته وکړم چې هغو خلکو ته چې اوس په دې خاوره کې اوسیږي، ماتې ورکړئ او هغوی به وشړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_31.mp3', '', 1761754199, 1761754199),
(41526, 'Exodus 23:32', 'Exodus', 23, 32, 'د هغوی یا د هغوی د خدایانو سره هېڅ ډول تړون مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_32.mp3', '', 1761754199, 1761754199),
(41527, 'Exodus 23:33', 'Exodus', 23, 33, 'هغوی مه پرېږدئ چې ستاسو په هېواد کې واوسیږي. که چېرې تاسو هغوی پرېږدئ، هغوی به تاسو زما په ضد په ګناه کولو باندې مجبور کړي. که چېرې تاسو د هغوی د خدایانو عبادت وکړئ، نو دا به ستاسو دپاره یو وژونکی دام وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus23_verse_33.mp3', '', 1761754199, 1761754199),
(41528, 'Psalms 100:1', 'Psalms', 100, 1, 'ای ټولې نړۍ، څښتن ته ووهئ د خوشحالۍ چیغې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms100_verse_1.mp3', '', 1761754199, 1761754199),
(41529, 'Psalms 100:2', 'Psalms', 100, 2, 'وکړئ عبادت د څښتن خدای په خوشحالۍ سره په سندرو د خوښۍ د هغه حضور ته راشئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms100_verse_2.mp3', '', 1761754199, 1761754199),
(41530, 'Psalms 100:3', 'Psalms', 100, 3, 'ومنئ دا چې څښتن خدای دی مونږ یو خلق کړي هغه او د هغه یو مونږه مونږ یو خلک د هغه او رمه یې د څړځای یو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms100_verse_3.mp3', '', 1761754199, 1761754199),
(41531, 'Psalms 100:4', 'Psalms', 100, 4, 'شکر کولو سره ننوځئ د هغه دروازو ته د هغه عبادتځای ته د ثنا سره ورننوځئ شکر یې ادا کړئ او صفت یې د نامه وکړئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms100_verse_4.mp3', '', 1761754199, 1761754199),
(41532, 'Psalms 100:5', 'Psalms', 100, 5, 'ځکه څښتن دی نېک او ده ابدي د هغه مینه وفاداري یې ده جاري د یو نسل نه تر بله پورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms100_verse_5.mp3', '', 1761754199, 1761754199),
(41533, 'Nahum 2:1', 'Nahum', 2, 1, 'ای نینوا، ته د حملې لاندې یې وساته خپلې جنګي کلاوې وڅاره لارې، جنګ ته تیار اوسه کړه راټول خپل قوتونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum2_verse_1.mp3', '', 1761754199, 1761754199),
(41534, 'Nahum 2:2', 'Nahum', 2, 2, 'څښتن به د اسراییلو هغه شان او شوکت چې دښمنانو یې له منځه وړی ؤ، لکه د یهودا د شان او شوکت په شان بېرته ورته راولي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum2_verse_2.mp3', '', 1761754199, 1761754199),
(41535, 'Nahum 2:3', 'Nahum', 2, 3, 'راروان کړي د دښمن لښکرو سره سپرونه د هغه عسکرو دی اغوستی سور لباس ځلیږي په ګاډیو لګېدلی فلز په هغه ورځ چې کړي تیار هغوی نو عسکر به کړي راپورته خپلې نېزې او خوځوي به هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum2_verse_3.mp3', '', 1761754199, 1761754199),
(41536, 'Nahum 2:4', 'Nahum', 2, 4, 'د توفان په شان روانې دي جنګي ګاډۍ کوڅو کې تېزې تېزې ځي راځي په څلور لارو کې هغوی پړقیږي څراغونو په شان او تېزې روانې دي لکه برېښنا په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum2_verse_4.mp3', '', 1761754199, 1761754199),
(41537, 'Nahum 2:5', 'Nahum', 2, 5, 'راټولیږي عسکري منصبداران څنګه چې ځي هغوی په لاره نو ښوییږي هغوی په چټکۍ سره روان دي هغوی د دېوالونو خواته چې کړي جوړ د محاصرې برج', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum2_verse_5.mp3', '', 1761754199, 1761754199),
(41538, 'Nahum 2:6', 'Nahum', 2, 6, 'دي خلاص شوي د اوبو بندونه او په رالوېدو ده ماڼۍ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum2_verse_6.mp3', '', 1761754199, 1761754199),
(41539, 'Nahum 2:7', 'Nahum', 2, 7, 'ملکه یې لوڅه شوې او وړل شوې هغه کوي ویر د هغې وینځې کړي زګېروي لکه کوترو په شان او له خفګانه وهي خپلې سینې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum2_verse_7.mp3', '', 1761754199, 1761754199),
(41540, 'Nahum 2:8', 'Nahum', 2, 8, 'ده نینوا لکه د ډنډ په شان چې اوبه وي ترې روانې وهي چیغې منصبداران: ودرېږئ! ودرېږئ! خو شاته نه ګوري هېڅوک', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum2_verse_8.mp3', '', 1761754199, 1761754199),
(41541, 'Nahum 2:9', 'Nahum', 2, 9, 'د دښمن عسکران چیغې وهي چې لوټ کړئ سپین زر، لوټ کړئ سره زر خزانې یې نه خلاصیږي د هر ډول قیمتي شیانو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum2_verse_9.mp3', '', 1761754199, 1761754199),
(41542, 'Nahum 2:10', 'Nahum', 2, 10, 'نینوا دی وران، شاړ او ویجاړ پروت دی کمزوري شوي زړونه او رپیږي یې زنګنونه ټول قوت یې تللی او رنګ یې الوتی له مخونو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum2_verse_10.mp3', '', 1761754199, 1761754199),
(41543, 'Nahum 2:11', 'Nahum', 2, 11, 'اوس دی چېرته نینوا هغه غار د زمرو هغه ځای چې ورکولو به هغوی خپلو بچو ته خواړه هغه ځای چې به ورتلل ورته نران او ښځینه زمریان او په کې خوندي وو د زمرو بچيان؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum2_verse_11.mp3', '', 1761754199, 1761754199),
(41544, 'Nahum 2:12', 'Nahum', 2, 12, 'زمري وکړ پوره ښکار خپلو بچو ته ټوټې ټوټې کوي هغه خپلې زمرۍ دپاره او ډکوي خپل غار د غوښو له ټوټو نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum2_verse_12.mp3', '', 1761754199, 1761754199),
(41545, 'Nahum 2:13', 'Nahum', 2, 13, 'مطلق قادر څښتن داسې وایي: «زه ستا په خلاف یم! زه به ستا جنګي ګاډۍ وسوځوم. ستا عسکر به په جنګ کې مړه شي او کوم شیان چې تا د نورو خلکو نه لوټ کړي دي، هغه به درڅخه بېرته واخلم. ستا د استازو غوښتنې به نور نه اورېدل کیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum2_verse_13.mp3', '', 1761754199, 1761754199),
(41546, 'Psalms 137:1', 'Psalms', 137, 1, 'مونږه په غاړه د سیندونو د بابل کښېناستو مونږ هلته وژړل په یاد د صهیون', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms137_verse_1.mp3', '', 1761754199, 1761754199),
(41547, 'Psalms 137:2', 'Psalms', 137, 2, 'مونږه ځوړند کړل خپل ربابونه د سپېدار په څانګو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms137_verse_2.mp3', '', 1761754199, 1761754199),
(41548, 'Psalms 137:3', 'Psalms', 137, 3, 'هغو کسانو چې نیولي یې وو مونږ هلته مونږ ته یې وویل چې سندرې وایئ چې زمونږ وخت ښه تېر شي مونږ ته ووایئ یوه سندره د صهیون په هکله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms137_verse_3.mp3', '', 1761754199, 1761754199),
(41549, 'Psalms 137:4', 'Psalms', 137, 4, 'څنګه کولای شو مونږ چې د څښتن سندره ووایو په پردي وطن کې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms137_verse_4.mp3', '', 1761754199, 1761754199),
(41550, 'Psalms 137:5', 'Psalms', 137, 5, 'ای اورشلیمه، که مې هېر کړلې ته نو زما ښي لاس دې شي شل چې بیا ونه وهم رباب', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms137_verse_5.mp3', '', 1761754199, 1761754199),
(41551, 'Psalms 137:6', 'Psalms', 137, 6, 'که زه تا یاد نه کړمه اورشلیمه که زه د ستا په هکله ونه کړم فکر چې ته یې لویه خوشحالي زما نو ودې نښلي زما ژبه په تالو کې چې بیا ونه وایم سندرې کله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms137_verse_6.mp3', '', 1761754199, 1761754199),
(41552, 'Psalms 137:7', 'Psalms', 137, 7, 'یاد کړه څښتنه، څه وکړل ادومیانو په هغه ورځ چې اورشلیم تسخیر شو یاد کړه چې څنګه دوی وهلې چیغې: «هغه وران کړئ، هغه وران کړئ وران یې کړئ تر تهدابونو پورې»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms137_verse_7.mp3', '', 1761754199, 1761754199),
(41553, 'Psalms 137:8', 'Psalms', 137, 8, 'ته به نابود شې ای بابله بختور دي هغه خلک چې تا سره وکړي هغه کار چې تا کړی ؤ زمونږ سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms137_verse_8.mp3', '', 1761754199, 1761754199),
(41554, 'Psalms 137:9', 'Psalms', 137, 9, 'بختور دي هغه خلک چې ماشومان ستا نیسي او وهي یې د ګټانو سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms137_verse_9.mp3', '', 1761754199, 1761754199),
(41555, 'Psalms 48:1', 'Psalms', 48, 1, 'څښتن خدای دی لوی هغه لایق دی د ثنا ټولې په هغه ښار کې چېرې اوسیږي چې په خپل سپېڅلي غر باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms48_verse_1.mp3', '', 1761754199, 1761754199),
(41556, 'Psalms 48:2', 'Psalms', 48, 2, 'لوړ او ښایسته دی صهیون د هغه لوی پاچا ښار کوم چې خوشحالي راوړي نړۍ ټولې ته دی د هغه لوړ غر په څېر کوم چې شمال کې پروت دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms48_verse_2.mp3', '', 1761754199, 1761754199),
(41557, 'Psalms 48:3', 'Psalms', 48, 3, 'خلکو ته وښودله خدای چې خوندیتوب دی د هغه سره دا خوندیتوب په پناه ځای د ښار کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms48_verse_3.mp3', '', 1761754199, 1761754199),
(41558, 'Psalms 48:4', 'Psalms', 48, 4, 'سره راټول شول پاچاهان چې د صهیون په غره حمله وکاندي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms48_verse_4.mp3', '', 1761754199, 1761754199),
