(41560, 'Psalms 48:6', 'Psalms', 48, 6, 'داسې درد او داسې وېره په دوی راغله لکه چې ښځو باندې راشي د زېږون په وخت کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms48_verse_6.mp3', '', 1761754199, 1761754199),
(41561, 'Psalms 48:7', 'Psalms', 48, 7, 'داسې نابود دې کړل هغوی لکه شرقي باد چې کشتۍ د ترشیش ماتې کړلې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms48_verse_7.mp3', '', 1761754199, 1761754199),
(41562, 'Psalms 48:8', 'Psalms', 48, 8, 'هغو کارو په هکله مونږ وو اورېدلي کوم چې کړي دي خدای هغه مو اوس ولیدل دا د مطلق قادر څښتن ښار کې د خپل خدای ښار کې هغه به خوندي وساتي تل ترتله دغه ښار', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms48_verse_8.mp3', '', 1761754199, 1761754199),
(41563, 'Psalms 48:9', 'Psalms', 48, 9, 'خدایه، د ستا د کور په منځ کې مونږ کوو فکر ستا د مینې په هکله د تلپاتې مینې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms48_verse_9.mp3', '', 1761754199, 1761754199),
(41564, 'Psalms 48:10', 'Psalms', 48, 10, 'نوم دې خپور شوی دی په ټول جهان کې ځکه خلک هرځای کې ثنا وایي ستا ته په انصاف سره حکومت کوې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms48_verse_10.mp3', '', 1761754199, 1761754199),
(41565, 'Psalms 48:11', 'Psalms', 48, 11, 'د صهیون خلک دې خوشحالي کوي! وي دې خوښي د یهودا کلیو کې ځکه ته سم قضاوتونه کوې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms48_verse_11.mp3', '', 1761754199, 1761754199),
(41566, 'Psalms 48:12', 'Psalms', 48, 12, 'ای د خدای قومه، د صهیون په شاوخوا وګرځئ تاسو حساب کړئ د هغه برجونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms48_verse_12.mp3', '', 1761754199, 1761754199),
(41567, 'Psalms 48:13', 'Psalms', 48, 13, 'په دېوالونو یې په غور سره نظر واچوئ او امتحان یې کړئ جنګي کلاوې راتلونکي نسل ته بیا تاسو دا ویلی شئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms48_verse_13.mp3', '', 1761754199, 1761754199),
(41568, 'Psalms 48:14', 'Psalms', 48, 14, 'چې دغه خدای دی تل ترتله زمونږ خدای رهنمایي به زمونږ ټول عمر وکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms48_verse_14.mp3', '', 1761754199, 1761754199),
(41569, 'Exodus 2:1', 'Exodus', 2, 1, 'په همدې وخت کې یو سړي چې د لاوي د قبیلې څخه ؤ د خپلې قبیلې د یوې ښځې سره واده وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_1.mp3', '', 1761754199, 1761754199),
(41570, 'Exodus 2:2', 'Exodus', 2, 2, 'هغه ښځه امیدواره شوه او زوی یې پیدا شو. کله چې هغې ولیدل چې ماشوم یې ښکلی دی، نو هغه یې د درېو میاشتو دپاره پټ وساته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_2.mp3', '', 1761754199, 1761754199),
(41571, 'Exodus 2:3', 'Exodus', 2, 3, 'کله چې هغې نور نه شو کولای چې هغه ماشوم پټ وساتي، نو د لوخو څخه یې یوه ټوکرۍ جوړه کړه او د قیرو پوښ یې ورته ورکړ. هغې ماشوم په ټوکرۍ کې واچاوه او د نیل د سیند په غاړه یې د لوخو په منځ کې لاهو کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_3.mp3', '', 1761754199, 1761754199),
(41572, 'Exodus 2:4', 'Exodus', 2, 4, 'د ماشوم خور لږه لېرې ودرېدله چې وګوري په ماشوم باندې څه کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_4.mp3', '', 1761754199, 1761754199),
(41573, 'Exodus 2:5', 'Exodus', 2, 5, 'په دې وخت کې د فرعون لور د لمبلو دپاره سیند ته راغله او د هغې وینځې د سیند په غاړه ګرځېدلې. په دې وخت کې هغې د لوخو په منځ کې هغه ټوکرۍ ولیدله او یوه ښځه یې ورولېږله چې هغه د اوبو څخه راوباسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_5.mp3', '', 1761754199, 1761754199),
(41574, 'Exodus 2:6', 'Exodus', 2, 6, 'کله چې د فرعون لور ټوکرۍ پرانیستله هغې ماشوم ولیده او ورباندې خفه شوه، ځکه چې هغه ژړل. هغې وویل: «دا یو عبرانی ماشوم دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_6.mp3', '', 1761754199, 1761754199),
(41575, 'Exodus 2:7', 'Exodus', 2, 7, 'ناڅاپه د ماشوم خور راغله او پوښتنه یې وکړه: «ایا ته غواړې چې زه لاړه شم او دغه ماشوم ته یوه عبرانۍ ښځه راولم چې تی ورکړي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_7.mp3', '', 1761754199, 1761754199),
(41576, 'Exodus 2:8', 'Exodus', 2, 8, 'د فرعون لور په ځواب کې وویل: «هو، لاړه شه.» نو انجلۍ لاړه او د ماشوم خپله مور یې راوستله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_8.mp3', '', 1761754199, 1761754199),
(41577, 'Exodus 2:9', 'Exodus', 2, 9, 'د فرعون لور هغې ښځې ته وویل: «دا ماشوم واخله او زما دپاره شیدې ورکوه او روزنه یې کوه. زه به تاته پیسې درکوم.» هغې ماشوم یووړ او د هغه روزنه یې کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_9.mp3', '', 1761754199, 1761754199),
(41578, 'Exodus 2:10', 'Exodus', 2, 10, 'کله چې دا ماشوم لوی شو، نو هغه یې د فرعون لور ته یووړ او هغې لکه د خپل زوی په شان وساته. هغې په دې ماشوم باندې موسی نوم کېښود، ځکه چې هغې د ځان سره وویل: «ما هغه د اوبو څخه راوویست.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_10.mp3', '', 1761754199, 1761754199),
(41579, 'Exodus 2:11', 'Exodus', 2, 11, 'کله چې موسی لوی شو، هغه د خپل قوم سره د لیدنې کتنې دپاره لاړ. هغه ولیدل چې د هغه قوم څومره سخت کار کاوه. هغه یو مصری ولیده چې یو عبرانی یې واهه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_11.mp3', '', 1761754199, 1761754199),
(41580, 'Exodus 2:12', 'Exodus', 2, 12, 'موسی یو خوا بل خوا وکتل، کله چې پوه شو څوک یې نه ویني، نو هغه مصری یې وواژه او په شګه کې یې پټ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_12.mp3', '', 1761754199, 1761754199),
(41581, 'Exodus 2:13', 'Exodus', 2, 13, 'کله چې موسی بله ورځ ووت، هغه دوه عبرانیان ولیدل چې یو د بل سره یې جګړه کوله. نو موسی له هغه یو څخه چې ملامت ؤ، پوښتنه وکړه: «ته ولې خپل عبرانی وطندار وهې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_13.mp3', '', 1761754199, 1761754199),
(41582, 'Exodus 2:14', 'Exodus', 2, 14, 'هغه سړي په ځواب کې وویل: «ته چا په مونږ باندې حاکم او قاضي ټاکلی یې؟ ته غواړې چې ما هم ووژنې لکه څنګه چې دې هغه مصری وواژه؟» موسی د دې خبرې په اورېدلو ووېرېده او د ځان سره یې وویل: «خلک پوه شوي دي چې ما څه کړي دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_14.mp3', '', 1761754199, 1761754199),
(41583, 'Exodus 2:15', 'Exodus', 2, 15, 'کله چې فرعون د موسی د دې کار څخه خبر شو، هغه د موسی د وژلو هڅه وکړه. خو هغه د مدیان خاورې ته وتښتېده. یوه ورځ موسی د څاه په غاړه ناست ؤ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_15.mp3', '', 1761754199, 1761754199),
(41584, 'Exodus 2:16', 'Exodus', 2, 16, 'چې د مدیان کاهن یترون اووه لورګانې راغلې چې اوبه راوباسي او د خپلې رمې دپاره اخورونه ډک کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_16.mp3', '', 1761754199, 1761754199),
(41585, 'Exodus 2:17', 'Exodus', 2, 17, 'خو څو شپنو د یترون لورګانې وشړلې. بیا موسی د هغوی سره د مرستې کولو دپاره ورغی او رمې ته یې اوبه ورکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_17.mp3', '', 1761754199, 1761754199),
(41586, 'Exodus 2:18', 'Exodus', 2, 18, 'کله چې د یترون لورګانې خپل کور ته راستنې شوې، نو پلار یې پوښتنه ورڅخه وکړه: «تاسو نن دومره وختي ولې راغلئ؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_18.mp3', '', 1761754199, 1761754199),
(41587, 'Exodus 2:19', 'Exodus', 2, 19, 'هغوی په ځواب کې وویل: «یو مصري د شپنو څخه وژغورلو او زمونږ دپاره یې اوبه راوویستلې او رمې ته یې ورکړې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_19.mp3', '', 1761754199, 1761754199),
(41588, 'Exodus 2:20', 'Exodus', 2, 20, 'یترون پوښتنه وکړه: «هغه چېرته دی؟ تاسو ولې هغه هلته پرېښود؟ هغه ته بلنه ورکړئ چې زمونږ سره ډوډۍ وخوري.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_20.mp3', '', 1761754199, 1761754199),
(41589, 'Exodus 2:21', 'Exodus', 2, 21, 'نو موسی راضي شو چې د یترون سره پاتې شي او هغه خپله لور صفوره موسی ته په نکاح ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_21.mp3', '', 1761754199, 1761754199),
(41590, 'Exodus 2:22', 'Exodus', 2, 22, 'کله چې د هغې زوی پیدا شو، موسی وویل: «زه به د هغه نوم جرشون کېږدم، ځکه چې زه په دې خاوره کې پردی یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_22.mp3', '', 1761754199, 1761754199),
(41591, 'Exodus 2:23', 'Exodus', 2, 23, 'وروسته له ډېرو کلونو د مصر پاچا مړ شو. اسراییلیانو لا هم د غلامۍ له امله فریادونه کول او د خدای څخه یې مرسته غوښتله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_23.mp3', '', 1761754199, 1761754199),
(41592, 'Exodus 2:24', 'Exodus', 2, 24, 'خدای د دوی فریاد واورېده او هغه لوظ یې را په یاد کړ چې د ابراهیم، اسحاق او یعقوب سره یې کړی ؤ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_24.mp3', '', 1761754199, 1761754199),
(41593, 'Exodus 2:25', 'Exodus', 2, 25, 'ځکه چې خدای ولیدل چې د هغه په قوم باندې څه تېریږي. نو هغه ورباندې ډېر اندېښمن شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus2_verse_25.mp3', '', 1761754199, 1761754199),
(41594, 'Job 18:1', 'Job', 18, 1, 'بيا شوحى بِلداد جواب ورکړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job18_verse_1.mp3', '', 1761754199, 1761754199),
(41595, 'Job 18:2', 'Job', 18, 2, '”تر کومې پورې به تۀ خبرې کوې؟ د مطلب خبره کوه، نو بيا به مونږ خبرې وکړُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job18_verse_2.mp3', '', 1761754199, 1761754199),
(41596, 'Job 18:3', 'Job', 18, 3, 'مونږ په ځناورو کښې ولې شمېرلے شُو؟ مونږ ستاسو په نظر کښې ولې کم عقلان يُو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job18_verse_3.mp3', '', 1761754199, 1761754199),
(41597, 'Job 18:4', 'Job', 18, 4, 'تۀ په غصه کښې هسې خپل ځان سوزوې، ستا دپاره دې دُنيا پرېښودلے شى څۀ، يا غرونه دې ستا دپاره د خپل ځائ نه لرې کړے شى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job18_verse_4.mp3', '', 1761754199, 1761754199),
(41598, 'Job 18:5', 'Job', 18, 5, 'په حقيقت کښې د بدعمله خلقو ډيوه ختمه کړے شوې ده، او بيا به د هغې شُغلې بلې نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job18_verse_5.mp3', '', 1761754199, 1761754199),
(41599, 'Job 18:6', 'Job', 18, 6, 'د هغوئ په خېمه کښې رڼا په تيارۀ بدله شوې ده، او د هغوئ دپاسه ډيوه مړه کړے شوې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job18_verse_6.mp3', '', 1761754199, 1761754199),
(41600, 'Job 18:7', 'Job', 18, 7, 'د هغوئ مضبوط قدمونه خطا شوى دى، او د هغوئ خپلو منصوبو هغوئ ناکامه کړى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job18_verse_7.mp3', '', 1761754199, 1761754199),
(41601, 'Job 18:8', 'Job', 18, 8, 'ځکه چې هغوئ په يو جال کښې انښتى دى، او هغوئ په يوه کنده کښې پرېوځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job18_verse_8.mp3', '', 1761754199, 1761754199),
(41602, 'Job 18:9', 'Job', 18, 9, 'د هغوئ پونده په دام کښې ګېريږى، او هغه يې کلک ونيسى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job18_verse_9.mp3', '', 1761754199, 1761754199),
(41603, 'Job 18:10', 'Job', 18, 10, 'يو جال په زمکه کښې پټ دے، او د هغوئ په لاره کښې يو دام پټ دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job18_verse_10.mp3', '', 1761754199, 1761754199),
(41604, 'Job 18:11', 'Job', 18, 11, 'هغوئ د هر طرف نه يريږى، او چې چرته هم ځى نو يره ورپسې وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job18_verse_11.mp3', '', 1761754199, 1761754199),
(41605, 'Job 18:12', 'Job', 18, 12, 'د هغوئ طاقت د لوږې په وجه ختم شوے دے، او تباهى د هغوئ د غلطۍ په انتظار کښې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job18_verse_12.mp3', '', 1761754199, 1761754199),
(41606, 'Job 18:13', 'Job', 18, 13, 'بيمارى د هغوئ څرمن خورى، او مرګ د هغوئ اندامونه خورى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job18_verse_13.mp3', '', 1761754199, 1761754199),
(41607, 'Job 18:14', 'Job', 18, 14, 'چې په کومو خېمو کښې هغوئ په حِفاظت کښې وُو نو هغوئ ويستلے شوى دى، او هغوئ د دهشت بادشاه ته راوستلے شوى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job18_verse_14.mp3', '', 1761754199, 1761754199),
(41608, 'Job 18:15', 'Job', 18, 15, 'د هغوئ په خېمو کښې هيڅ څوک هم پاتې نۀ دى، او د هغوئ د کورونو دپاسه د ګوګړو باران دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job18_verse_15.mp3', '', 1761754199, 1761754199),
(41609, 'Job 18:16', 'Job', 18, 16, 'د هغوئ جرړې لاندې اوچې شوې دى، او د هغوئ څانګې پاس مړاوې شوې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job18_verse_16.mp3', '', 1761754199, 1761754199),
(41610, 'Job 18:17', 'Job', 18, 17, 'د هغوئ نوم به د زمکې نه ختم شى، او په لارو کوڅو کښې به د هغوئ ذکر نۀ کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job18_verse_17.mp3', '', 1761754199, 1761754199);